    15	function datePartsInTimezone(date) {
    16	  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    17	    if (type !== "literal") parts[type] = parseInt(value, 10)
    18	    return parts
    19	  }, {})
    20	}
