const MS_PER_DAY = 1000 * 60 * 60 * 24

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

// Formats a Date into human words in the browser's own timezone. The server
// only ever sends the raw timestamp; the viewer's clock decides what it says.
export function formatTimestamp(date, format = "relative", now = new Date()) {
  switch (format) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDate(date, now)
    case "date_with_year":
      return formatDate(date, now, true)
    case "long_date":
      return formatLongDate(date, now)
    case "date_time":
      return formatDateTime(date, now)
    default:
      return formatRelative(date, now)
  }
}

export function formatRelative(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return date <= now ? formatTime(date) : "today"
  } else if (days === -1) {
    return "yesterday"
  } else if (days === 1) {
    return "tomorrow"
  } else if (days < -1 && days > -7) {
    return `${-days} days ago`
  } else if (days > 1 && days < 7) {
    return `in ${days} days`
  } else {
    return formatDate(date, now)
  }
}

function formatTime(date) {
  return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(date)
}

function formatDate(date, now, alwaysIncludeYear = false) {
  const options = { month: "short", day: "numeric" }
  if (alwaysIncludeYear || date.getFullYear() !== now.getFullYear()) {
    options.year = "numeric"
  }
  return new Intl.DateTimeFormat("en-US", options).format(date)
}

function formatLongDate(date, now) {
  const options = { weekday: "long", month: "long", day: "numeric" }
  if (date.getFullYear() !== now.getFullYear()) {
    options.year = "numeric"
  }
  return new Intl.DateTimeFormat("en-US", options).format(date)
}

function formatDateTime(date, now) {
  const options = { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }
  if (date.getFullYear() !== now.getFullYear()) {
    options.year = "numeric"
  }
  return new Intl.DateTimeFormat("en-US", options).format(date)
}
